class Solution:
    def sumPrefixScores(self, words: list[str]) -> list[int]:
        trie = {}
        for word in words:
            node = trie
            for c in word:
                if c not in node:
                    node[c] = {'#': 0}
                node = node[c]
                node['#'] += 1
        result = []
        for word in words:
            node = trie
            score = 0
            for c in word:
                node = node[c]
                score += node['#']
            result.append(score)
        return result

